/* The private resource calendar uses bookings; client calendars use confirmed job schedules only. */
let privateCalendarMode='month',privateCalendarDay=new Date(Date.now()+2*3600000).toISOString().slice(0,10),privateSubbieFilter='all';
const dateKey=d=>d.toISOString().slice(0,10),keyDate=k=>new Date(k+'T00:00:00Z');
function calendarDayKeys(){const d=keyDate(privateCalendarDay);if(privateCalendarMode==='week'){const monday=new Date(d);monday.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);return Array.from({length:7},(_,i)=>{let x=new Date(monday);x.setUTCDate(x.getUTCDate()+i);return dateKey(x)})}const first=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),1)),offset=(first.getUTCDay()+6)%7,count=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();return Array.from({length:offset+count},(_,i)=>i<offset?null:dateKey(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),i-offset+1))))}
function filteredPrivateBookings(){if(role!=='sevlink')return [];return state.privateBookings.filter(b=>(privateSubbieFilter==='all'||b.subbie===privateSubbieFilter)&&(plannerFilter==='All bookings'||b.status===plannerFilter)).sort((a,b)=>a.when.localeCompare(b.when))}
function isClientPublished(b){const j=bookingJob(b);return !!j&&j.schedule?.status==='Confirmed'&&j.schedule.when===b.when}
function bookingCalendarCard(b){const j=bookingJob(b),s=bookingSubbie(b);return `<button class="private-cal-event ${b.status==='Declined'||b.status==='Cancelled'?'inactive':b.status==='Accepted'?'accepted':''}" onclick="privateBookingDetail('${b.id}')"><b>${b.when.slice(11)} · ${esc(s?.name||'Unassigned')}</b><strong class="calendar-issue">${esc(j?.title||j?.category||'Maintenance visit')}</strong><span>${esc(property(j?.property)?.name)}</span><small>${esc(j?.ref)} · ${esc(b.status)}</small><small>${b.status==='Attended'?'✓ Attended':b.onSiteAt?'● On site · job updated':isClientPublished(b)?'✓ Client sees Sevlink attending':'Private / not confirmed with client'}</small></button>`}
const plannerBeforeCalendar=renderPrivatePlanner;
renderPrivatePlanner=function(){if(!plannerAllowed())return;if(plannerTab!=='calendar'){plannerBeforeCalendar();$('.tabs').insertAdjacentHTML('afterbegin','<button onclick="plannerTab=\'calendar\';renderPrivatePlanner()">Calendar</button>');return}const bookings=filteredPrivateBookings(),days=calendarDayKeys(),d=keyDate(privateCalendarDay),title=privateCalendarMode==='month'?d.toLocaleDateString('en-ZA',{month:'long',year:'numeric',timeZone:'UTC'}):new Date(days[0]+'T00:00:00Z').toLocaleDateString('en-ZA',{day:'numeric',month:'short',timeZone:'UTC'})+' – '+new Date(days[6]+'T00:00:00Z').toLocaleDateString('en-ZA',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});const today=new Date(Date.now()+2*3600000).toISOString().slice(0,10);app.innerHTML=heading('Your private attendance calendar.','Open any booking for who is attending, where, when, instructions and private notes.','<button class="primary" onclick="bookingForm()">＋ Assign subbie</button>')+`<div class="banner"><b>SEVLINK STAFF ONLY · DEMO</b><br>Private bookings show the real subbie assignment. Confirmed client appointments appear as <b>Sevlink attending</b> without the subbie identity, cost or internal notes.</div><div class="tabs"><button class="selected" onclick="plannerTab='calendar';renderPrivatePlanner()">Calendar</button><button onclick="plannerTab='bookings';renderPrivatePlanner()">Assignments & dates</button><button onclick="plannerTab='subbies';renderPrivatePlanner()">Subbie directory</button></div><div class="panel"><div class="planner-controls"><div class="toolbar"><button class="secondary" onclick="movePrivateCalendar(-1)" aria-label="Previous calendar period">←</button><h2>${title}</h2><button class="secondary" onclick="movePrivateCalendar(1)" aria-label="Next calendar period">→</button><button class="secondary" onclick="privateCalendarDay='${today}';renderPrivatePlanner()">Today</button></div><div class="toolbar"><button class="${privateCalendarMode==='month'?'primary':'secondary'}" onclick="privateCalendarMode='month';renderPrivatePlanner()">Month</button><button class="${privateCalendarMode==='week'?'primary':'secondary'}" onclick="privateCalendarMode='week';renderPrivatePlanner()">Week</button></div></div><div class="planner-controls"><select id="privateSubbieFilter" aria-label="Filter by subbie"><option value="all">All subbies</option>${state.subbies.map(s=>`<option value="${s.id}" ${privateSubbieFilter===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><select id="privateStatusFilter" aria-label="Filter booking status">${['All bookings','Awaiting response','Accepted','Declined','Attended','Cancelled'].map(s=>`<option ${plannerFilter===s?'selected':''}>${s}</option>`).join('')}</select><small class="muted">All times in SAST · click a booking to open its full job card</small></div><div class="private-calendar-scroll"><div class="calendar-grid private-calendar ${privateCalendarMode==='week'?'week-view':''}">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(day=>`<div class="cal-head">${day}</div>`).join('')}${days.map(day=>day?`<div class="cal-day ${day===today?'today':''}"><div class="cal-date"><b>${Number(day.slice(-2))}</b>${privateCalendarMode==='week'?'<small>'+keyDate(day).toLocaleDateString('en-ZA',{month:'short',timeZone:'UTC'})+'</small>':''}</div>${bookings.filter(b=>b.when.startsWith(day)).map(bookingCalendarCard).join('')}</div>`:'<div class="cal-day outside-month"></div>').join('')}</div></div><div class="toolbar" style="margin-top:18px"><span class="badge Accepted">Accepted</span><span class="badge Awaiting">Awaiting response</span><small class="muted">Client calendar changes only when you confirm an agreed appointment.</small></div></div><div class="panel" style="margin-top:20px"><h2>Bookings in this view</h2>${bookings.filter(b=>days.includes(b.when.slice(0,10))).map(b=>{const j=bookingJob(b);return `<div class="listline toolbar"><div style="flex:1"><b>${esc(bookingSubbie(b)?.name)}</b><p>${esc(property(j?.property)?.name)} · ${attendanceTime(b.when)}<br>${esc(j?.title)}<br>${isClientPublished(b)?'Client calendar: Sevlink attending':'Client appointment not confirmed for this time'}</p></div><button class="secondary" onclick="privateBookingDetail('${b.id}')">Open job card →</button></div>`}).join('')||'<p>No assignments in this period. Move to another month, change filters or add a booking.</p>'}</div>`;$('#privateSubbieFilter').onchange=e=>{privateSubbieFilter=e.target.value;renderPrivatePlanner()};$('#privateStatusFilter').onchange=e=>{plannerFilter=e.target.value;renderPrivatePlanner()}};
function movePrivateCalendar(delta){const d=keyDate(privateCalendarDay);if(privateCalendarMode==='week')d.setUTCDate(d.getUTCDate()+7*delta);else{d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+delta)}privateCalendarDay=dateKey(d);renderPrivatePlanner()}
const summaryBeforePrivateCalendar=scheduleSummary;
scheduleSummary=function(j){const summary=summaryBeforePrivateCalendar(j);return j.schedule?.status==='Confirmed'?summary.replace('✓ Confirmed attendance','✓ Sevlink attending — confirmed appointment'):summary};
